export type PendingQuestion = { toolCallId: string; input: AskQuestionInput };

export type AdvanceResult = {
  messages: ModelMessage[];
  usage: TokenUsage;
  roundLatenciesMs: number[];
  promptId: string;
} & (
  | { status: "awaiting_answer"; pending: PendingQuestion }
  | { status: "completed"; entry: { summary: string; answers: Record<string, Answer> } }
);

/** Rebuild recorded answers + asked questions from the transcript alone. */
function replayTranscript(messages: ModelMessage[]): {
  answers: Record<string, Answer>;
  asked: Set<string>;
  pending: PendingQuestion | undefined;
} {
  const answers: Record<string, Answer> = {};
  const asked = new Set<string>();
  const answeredCalls = new Set<string>();
  let pending: PendingQuestion | undefined;

  for (const message of messages) {
    if (typeof message.content === "string") {
      continue;
    }
    for (const part of message.content) {
      if (message.role === "assistant" && part.type === "tool-call") {
        if (part.toolName === "ask_question") {
          const input = askQuestionInput.safeParse(part.input);
          if (input.success) {
            asked.add(input.data.question_id);
            pending = { toolCallId: part.toolCallId, input: input.data };
          }
        } else if (part.toolName === "record_answer") {
          const input = recordAnswerInput.safeParse(part.input);
          if (input.success) {
            answers[input.data.question_id] = input.data.answer;
          }
        }
      } else if (message.role === "tool" && part.type === "tool-result") {
        answeredCalls.add(part.toolCallId);
      }
    }
  }
  if (pending && answeredCalls.has(pending.toolCallId)) {
    pending = undefined;
  }
  return { answers, asked, pending };
}

/**
 * Advance a session by as many model rounds as possible: from empty (new
 * session) or from a transcript + the answer to its pending question, up to
 * either the next ask_question or completion. Stateless — everything is
 * reconstructed from the transcript, so callers (CLI loop, HTTP endpoint)
 * own persistence.
 */
export async function advanceSession(opts: {
  questionSet: QuestionSet;
  model: LanguageModel;
  messages: ModelMessage[];
  answer?: SessionAnswer;
  temperature?: number;
  attribution?: { distinctId: string; sessionId: string };
  promptId?: string;
}): Promise<AdvanceResult> {
  const { questionSet, model, temperature, attribution } = opts;
  const prompt = resolvePrompt(opts.promptId);
  const replay = replayTranscript(opts.messages);
  const answers = replay.answers;
  const asked = replay.asked;
  const roundLatenciesMs: number[] = [];
  const usage = emptyUsage();
  let summary: string | undefined;

  const messages: ModelMessage[] =
    opts.messages.length > 0
      ? [...opts.messages]
      : [{ role: "user", content: "I am ready to start my journaling session." }];

  if (replay.pending) {
    if (opts.answer?.toolCallId !== replay.pending.toolCallId) {
      throw new Error("answer does not match the pending question");
    }
    messages.push({
      role: "tool",
      content: [
        {
          type: "tool-result",
          toolCallId: replay.pending.toolCallId,
          toolName: "ask_question",
          output: { type: "json", value: { answer: opts.answer.value } },
        },
      ],
    });
  }

  const tools = buildSessionTools(questionSet, answers, asked, (s) => {
    summary = s;
  });
  const guard = roundGuard(questionSet);
  // Stateless guard: rounds already spent live in the transcript.
  for (const m of messages) {
    if (m.role === "assistant") {
      guard.next();
    }
  }

  while (summary === undefined) {
    guard.next();
    const startedAt = performance.now();
    const result = await generateText({
      model,
      instructions: prompt.build(questionSet),
      tools,
      stopWhen: isStepCount(1),
      maxOutputTokens: MAX_OUTPUT_TOKENS_PER_ROUND,
      ...(temperature === undefined ? {} : { temperature }),
      ...(attribution === undefined
        ? {}
        : { runtimeContext: { ...attribution, promptId: prompt.id } }),
      telemetry: SESSION_TELEMETRY,
      messages,
    });
    roundLatenciesMs.push(performance.now() - startedAt);
    messages.push(...result.response.messages);
    addUsage(usage, result.usage);

    if (result.finishReason !== "tool-calls") {
      continue;
    }
    const ask = result.toolCalls.find((c) => c.toolName === "ask_question");
    if (ask) {
      asked.add((ask.input as AskQuestionInput).question_id);
      return {
        status: "awaiting_answer",
        messages,
        usage,
        roundLatenciesMs,
        promptId: prompt.id,
        pending: {
          toolCallId: ask.toolCallId,
          input: ask.input as AskQuestionInput,
        },
      };
    }
  }

  return {
    status: "completed",
    messages,
    usage,
    roundLatenciesMs,
    promptId: prompt.id,
    entry: { summary, answers },
  };
}
